import{_ as a,a as t}from"./chunks/Fixpipe_Channel_Split_with_dirty.a3A2YLlc.js";import{_ as i,o as l,a as p,b as n}from"./app.CIoiBgkh.js";const A=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"矩阵搬出关键特性说明","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/cube_store_key_features"},{"text":"F32 Channel Split","link":"/api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split.md","filePath":"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split.md","outlineHeaders":[{"level":2,"title":"特性说明","slug":"特性说明","link":"#特性说明"},{"level":2,"title":"特性约束","slug":"特性约束","link":"#特性约束"},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例"}],"lastUpdated":1789544578000}'),s={name:"api/SIMD-API/c_api/cube_datamove/cube_store_key_features/F32-Channel-Split.md"};function r(_,e,d,c,o,u){return l(),p("div",null,[...e[0]||(e[0]=[n('<div><article class="markdown-body"><h1>F32 Channel Split</h1><h2 id="特性说明">特性说明<a class="header-anchor" href="#特性说明">​</a></h2><p>矩阵计算的搬出过程中对于目标类型为f32，如果开启了Channel Split（通道拆分），硬件就能够将16×16的分形矩阵转换为16×8的小z分形矩阵，此时每个16×16的分形矩阵将被拆分为2个独立的16×8的小z分形矩阵。</p><h2 id="特性约束">特性约束<a class="header-anchor" href="#特性约束">​</a></h2><div data-filter="A3,910b"><ul><li><p>针对如下产品型号：</p><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品</p></div><p>当Fixpipe指令的输入和输出数据类型都为float，Nz输出到GM，并且不开启Nz2ND与unitFlag时，才能够开启Channel Split功能。</p></li></ul></div><div data-filter="950"><ul><li>针对Ascend 950PR/Ascend 950DT，当Fixpipe指令的输入和输出数据类型都为float,Nz输出到GM，并且不开启Nz2ND、Nz2DN与unitFlag时，才能够开启Channel Split功能。当前搬出到L1 Buffer和Unified Buffer（UB）不支持该功能。</li></ul></div><h2 id="使用示例">使用示例<a class="header-anchor" href="#使用示例">​</a></h2><p>如下图所示，当开启Channel Split功能后，shape为[64,32]的源操作数将会被拆分为16个独立的16x8分形矩阵。</p><p><strong>图1</strong> F32 Channel Split示意图（无无效数据）</p><p><img src="'+a+'" alt></p><p>当开启Channel Split功能后，n_size（源Nz矩阵在N方向上的大小）必须为8的倍数。如下图所示，shape为[64,24]的源操作数将会被拆分为3列16x8分形矩阵。</p><p><strong>图2</strong> F32 Channel Split示意图（有无效数据）</p><p><img src="'+t+'" alt></p></article></div>',1)])])}const S=i(s,[["render",r]]);export{A as __pageData,S as default};
